CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, discord_name TEXT NOT NULL, nickname TEXT NOT NULL, avatar TEXT, discord_avatar TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pending(code_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE, nick TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS links(user_id TEXT PRIMARY KEY, nick TEXT NOT NULL, nick_lower TEXT NOT NULL UNIQUE, uuid TEXT, linked_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS fails(nick_lower TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS fails_idx ON fails(nick_lower, ts);
